const timeoutCheck = Math.max(5000, process.env.CFN_REDIS_TIMEOUT_MS || 10000);

Enhance error messages:

```typescript
catch (error: any) {
  if (error.message.includes('ECONNREFUSED')) {
    console.error(`[CFN Protocol] ✗ Redis connection refused at ${redisHost}:${redisPort}`);
    console.error(`[CFN Protocol] Try: redis-server --daemonize yes`);
  } else if (error.message.includes('WRONGPASS')) {
    console.error(`[CFN Protocol] ✗ Redis authentication failed`);
    console.error(`[CFN Protocol] Check CFN_REDIS_PASSWORD environment variable`);
  } else {
    console.error(`[CFN Protocol] ✗ Redis error: ${error.message}`);
  }
  throw error;
}
```

